create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text unique not null,role text not null default 'user' check(role in('user','admin')),created_at timestamptz default now());
create table if not exists public.anime(id uuid primary key default gen_random_uuid(),title text not null,synopsis text not null default '',genre text not null default 'Action',kind text not null default 'Series' check(kind in('Series','Movie')),poster_url text not null default '',banner_url text not null default '',status text not null default 'Ongoing',created_by uuid references auth.users(id),created_at timestamptz default now());
create table if not exists public.episodes(id uuid primary key default gen_random_uuid(),anime_id uuid not null references public.anime(id) on delete cascade,title text not null,episode_number integer not null check(episode_number>0),video_url text not null,subtitle_url text not null default '',created_at timestamptz default now(),unique(anime_id,episode_number));
create table if not exists public.watchlist(user_id uuid not null references auth.users(id) on delete cascade default auth.uid(),anime_id uuid not null references public.anime(id) on delete cascade,created_at timestamptz default now(),primary key(user_id,anime_id));
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ declare uname text; begin uname:=coalesce(new.raw_user_meta_data->>'username',split_part(new.email,'@',1)); insert into public.profiles(id,username) values(new.id,uname); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security;alter table public.anime enable row level security;alter table public.episodes enable row level security;alter table public.watchlist enable row level security;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin'); $$;
create policy "profile read own" on public.profiles for select to authenticated using(id=auth.uid());
create policy "anime read auth" on public.anime for select to authenticated using(true);
create policy "anime admin insert" on public.anime for insert to authenticated with check(public.is_admin());
create policy "anime admin update" on public.anime for update to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "anime admin delete" on public.anime for delete to authenticated using(public.is_admin());
create policy "episodes read auth" on public.episodes for select to authenticated using(true);
create policy "episodes admin insert" on public.episodes for insert to authenticated with check(public.is_admin());
create policy "episodes admin update" on public.episodes for update to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "episodes admin delete" on public.episodes for delete to authenticated using(public.is_admin());
create policy "watchlist own read" on public.watchlist for select to authenticated using(user_id=auth.uid());
create policy "watchlist own insert" on public.watchlist for insert to authenticated with check(user_id=auth.uid());
create policy "watchlist own delete" on public.watchlist for delete to authenticated using(user_id=auth.uid());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('anime-art','anime-art',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy "anime art public read" on storage.objects for select using(bucket_id='anime-art');
create policy "anime art admin upload" on storage.objects for insert to authenticated with check(bucket_id='anime-art' and public.is_admin());
create policy "anime art admin update" on storage.objects for update to authenticated using(bucket_id='anime-art' and public.is_admin()) with check(bucket_id='anime-art' and public.is_admin());
create policy "anime art admin delete" on storage.objects for delete to authenticated using(bucket_id='anime-art' and public.is_admin());
